def validate_context(value):
    if not isinstance(value, dict) or set(value) - {"plan_id", "plan_ids", "mode", "universe", "symbols", "conditions"}:
        raise ValueError("invalid opportunity fields")
    if not isinstance(value.get("plan_id"), str) or not isinstance(value.get("mode"), str) or value["plan_id"] not in {*PLANS, "custom"} or value["mode"] not in MODES:
        raise ValueError("invalid opportunity plan or mode")
    if not isinstance(value.get("universe"), str) or value["universe"] not in {"csi300", "watchlist"}:
        raise ValueError("invalid opportunity universe")
    symbols = value.get("symbols") or []
    if not isinstance(symbols, list) or len(symbols) > 50:
        raise ValueError("invalid opportunity symbols")
    if any(not isinstance(symbol, str) or not SYMBOL.fullmatch(symbol) for symbol in symbols):
        raise ValueError("invalid opportunity symbol")
    if len(set(symbols)) != len(symbols):
        raise ValueError("duplicate opportunity symbols")
    if value["universe"] == "watchlist" and not symbols:
        raise ValueError("watchlist is empty")
    conditions = value.get("conditions", "")
    if not isinstance(conditions, str) or len(conditions) > 5000:
        raise ValueError("invalid opportunity conditions")
    if value["plan_id"] == "custom" and not conditions.strip():
        raise ValueError("custom conditions required")
    result = {"plan_id": value["plan_id"], "mode": value["mode"], "universe": value["universe"],
              "symbols": symbols, "conditions": conditions}
    if "plan_ids" in value:
        ids = value["plan_ids"]
        if (not isinstance(ids, list) or not 2 <= len(ids) <= 5
            or any(not isinstance(item, str) or item not in PLANS or item == "custom" for item in ids)
            or len(set(ids)) != len(ids) or ids[0] != value["plan_id"]):
            raise ValueError("invalid opportunity combination")
        result["plan_ids"] = ids
    return result


def opportunity_context(config):
    value = config.get("mona_opportunity") if isinstance(config, dict) else None
    if value is None:
        return None
    return validate_context(value)


