def _artifact_path(session_id, attempt_id):
    if not OBJECT_ID.fullmatch(session_id) or not OBJECT_ID.fullmatch(attempt_id):
        raise ValueError("invalid session identity")
    root = (get_runtime_root() / "opportunity-research").resolve()
    path = (root / session_id / (attempt_id + ".json")).resolve()
    if not path.is_relative_to(root):
        raise ValueError("opportunity artifact outside root")
    return path


def save_candidates(session_id, attempt_id, tool_trail, candidates, as_of, limitations, *, context=None, quant_results=None):
    context, quant_results = context or {}, quant_results or {}
    selected = context.get("plan_ids", [])
    if isinstance(candidates, str):
        candidates = json.loads(candidates)
    if isinstance(limitations, str):
        limitations = json.loads(limitations)
    if not isinstance(candidates, list) or len(candidates) > 50:
        raise ValueError("invalid candidate list")
    observed = {}
    for entry in tool_trail:
        if entry.get("status") != "ok" or not isinstance(entry.get("call_id"), str) or entry.get("tool") not in {
                    "screen_market", "get_market_data", "get_stock_profile", "get_financial_statements",
                    "get_cn_announcements", "get_stock_news", "web_search", "read_url",
                    "factor_analysis", "alpha_bench", "alpha_compare", "screen_opportunities",
        }:
            continue
        preview = entry.get("preview", "")
        if not isinstance(preview, str) or not preview.strip():
            continue
        try:
            data = json.loads(preview)
        except json.JSONDecodeError:
            data = None  # Long native previews can end before the JSON terminator.
        if isinstance(data, dict) and (data.get("error") or data.get("status") == "error" or data.get("ok") is False):
            continue
        if data == {} or data == [] or data == {"data": []}:
            continue
        plan_id = entry.get("arguments", {}).get("plan_id") if isinstance(entry.get("arguments"), dict) else None
        if entry.get("tool") == "screen_opportunities" and plan_id in quant_results:
            entry = {**entry, "observed_symbols": [item["symbol"] for item in quant_results[plan_id]["candidates"]]}
        observed[entry["call_id"]] = entry
    rows, seen = [], set()
    for item in candidates:
        symbol = item.get("symbol")
        if not isinstance(symbol, str) or not SYMBOL.fullmatch(symbol) or symbol in seen:
            raise ValueError("invalid or duplicate candidate")
        refs = item.get("evidence_call_ids")
        if refs is None:
            refs = [call_id for call_id, entry in observed.items()
                    if symbol[:6] in json.dumps(entry, ensure_ascii=False)]
        if not isinstance(refs, list) or not refs or any(not isinstance(ref, str) or ref not in observed for ref in refs):
            raise ValueError("candidate requires real successful data tool references")
        # An observed symbol must occur in the actual result or its query identity.
        if not any(symbol[:6] in json.dumps(observed[ref], ensure_ascii=False) for ref in refs):
            raise ValueError("candidate not observed in cited tool calls")
        support, risks = item.get("support"), item.get("risks")
        if any(not isinstance(values, list) or not 1 <= len(values) <= 8
               or any(not isinstance(text, str) or not text.strip() or len(text) > 1000 for text in values)
               for values in (support, risks)):
            raise ValueError("candidate support and risks required")
        seen.add(symbol)
        row = {"symbol": symbol, "rank": len(rows) + 1, "support": support, "risks": risks,
               "evidence": [{"tool": observed[ref]["tool"], "call_id": ref} for ref in refs]}
        if selected:
            checks = item.get("checks")
            if (not isinstance(checks, list) or len(checks) != len(selected)
                or any(not isinstance(check, dict) for check in checks)
                or {check.get("plan_id") for check in checks} != set(selected)):
                raise ValueError("each selected direction requires a candidate check")
            evidence_tools = {
                "fundamental": {"get_stock_profile", "get_financial_statements", "web_search", "read_url"},
                "sector": {"screen_market", "get_stock_profile", "get_stock_news", "web_search", "read_url"},
                "event": {"get_cn_announcements", "get_stock_news", "web_search", "read_url"},
            }
            for check in checks:
                key, reason = check["plan_id"], check.get("reason")
                if check.get("status") != "supported" or not isinstance(reason, str) or not reason.strip() or len(reason) > 1000:
                    raise ValueError("conflicting or missing directions must be excluded from candidates")
                if key in {"multifactor", "low_volatility"}:
                    evidence = quant_results.get(key)
                    if not evidence or symbol not in {row["symbol"] for row in evidence["candidates"][:5]}:
                        raise ValueError("candidate must be in each selected quantitative method's actual Top5")
                    if evidence["as_of"][:10] != as_of[:10]:
                        raise ValueError("quantitative evidence cutoff does not match candidate cutoff")
                elif not any(observed[ref]["tool"] in evidence_tools[key]
                             and symbol[:6] in json.dumps(observed[ref], ensure_ascii=False) for ref in refs):
                    raise ValueError("selected research direction requires real candidate source evidence")
            row["checks"] = checks
        rows.append(row)
    if not isinstance(as_of, str) or len(as_of) > 100:
        raise ValueError("invalid research data time")
    if not isinstance(limitations, list) or len(limitations) > 20 or any(not isinstance(s, str) or len(s) > 1000 for s in limitations):
        raise ValueError("invalid limitations")
    result = {"session_id": session_id, "attempt_id": attempt_id, "as_of": as_of,
              "candidates": rows, "limitations": limitations, "kind": "research",
              "saved_at": datetime.now(ZoneInfo("Asia/Shanghai")).isoformat()}
    if selected:
        result["composition"] = {"plan_ids": selected, "rule": "all_selected", "backtest_status": "not_run",
                                 "methods": list(quant_results.values())}
    _save_projection(session_id, attempt_id, result)
    return {"saved": True, "candidate_count": len(rows), "session_id": session_id, "attempt_id": attempt_id}


def _save_projection(session_id, attempt_id, result):
    path = _artifact_path(session_id, attempt_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix("." + uuid.uuid4().hex + ".tmp")
    try:
        temporary.write_text(json.dumps(result, ensure_ascii=False, allow_nan=False), encoding="utf-8")
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)


def _session_result(store, session_id, attempt_id):
    session = store.get_session(session_id)
    if session is None or opportunity_context(session.config) is None:
        raise HTTPException(status_code=404, detail="Opportunity session not found")
    explicit_attempt = attempt_id is not None
    attempt_id = attempt_id or session.last_attempt_id
    attempt = store.get_attempt(session_id, attempt_id) if attempt_id else None
    if explicit_attempt and attempt is None:
        raise HTTPException(status_code=404, detail="Attempt not in this opportunity session")
    if attempt is not None and attempt.session_id != session_id:
        raise HTTPException(status_code=404, detail="Attempt not in this opportunity session")
    result = {"session_id": session_id, "attempt_id": attempt_id, "candidates": [],
              "context": opportunity_context(session.config), "limitations": []}
    if attempt is None or attempt.status.value != "completed":
        return result
    path = _artifact_path(session_id, attempt.attempt_id)
    if not path.is_file():
        result["limitations"] = ["本次研究已完成，但未生成可核实的结构化候选；可查看完整报告与覆盖说明。"]
        return result
    if path.stat().st_size > 512 * 1024 or path.is_symlink():
        raise ValueError("invalid opportunity artifact")
    data = json.loads(path.read_text(encoding="utf-8"))
    if data.get("session_id") != session_id or data.get("attempt_id") != attempt.attempt_id:
        raise ValueError("opportunity artifact identity mismatch")
    return {**result, **data}


def load_research_universe(context):
    if context["universe"] == "watchlist":
        return list(context["symbols"]), {}, {"source": "user_watchlist", "as_of": date.today().isoformat()}
    # Fixed official index roster; never substitute a small static sample.
    import requests

    url = "https://oss-ch.csindex.com.cn/static/html/csindex/public/uploads/file/autofile/cons/000300cons.xls"
    response = requests.get(url, timeout=20)
    response.raise_for_status()
    if len(response.content) > 2 * 1024 * 1024:
        raise ValueError("index roster exceeds expected size")
    frame = pd.read_excel(BytesIO(response.content))
    if frame.shape[1] < 9 or len(frame) < 250 or len(frame) > 350:
        raise ValueError("official CSI300 roster is incomplete")
    codes, names = [], {}
    for _, row in frame.iterrows():
        code = str(row.iloc[4]).split(".")[0].zfill(6)
        exchange = "SH" if code.startswith("6") else "SZ" if code.startswith(("0", "3")) else None
        if exchange is None:
            raise ValueError("unexpected index constituent market")
        symbol = code + "." + exchange
        if symbol not in names:
            codes.append(symbol)
        names[symbol] = str(row.iloc[5])
    return codes, names, {"source": "csindex_official_current_constituents", "as_of": str(frame.iloc[0, 0]),
                          "retrieved_at": datetime.now(ZoneInfo("Asia/Shanghai")).isoformat(),
                          "sha256": hashlib.sha256(response.content).hexdigest()}


