    cutoff = now.date() - timedelta(days=1) if now.hour < 15 else now.date()
    start = cutoff - timedelta(days=1300)
    fetched, dropped = {}, []

    def fetch(symbol):
        frames = DataLoader().fetch([symbol], start.isoformat(), cutoff.isoformat())
        frame = frames.get(symbol)
        if frame is None or frame.empty:
            return symbol, None, "行情来源未返回日线"
        if frame.attrs.get("adjustment") != "split_dividend":
            return symbol, None, "缺少可核实的乘法复权日线"
        frame = frame.loc[frame.index.normalize() <= pd.Timestamp(cutoff)].copy()
        frame["volume"] = pd.to_numeric(frame["volume"], errors="coerce") * 100
        if len(frame) < 260:
            return symbol, None, "有效日线不足260个交易日"
        return symbol, frame, None

    with ThreadPoolExecutor(max_workers=6) as pool:
        jobs = {pool.submit(fetch, symbol): symbol for symbol in symbols}
        for index, future in enumerate(as_completed(jobs), 1):
            symbol = jobs[future]
            try:
                symbol, frame, reason = future.result()
            except (OSError, ValueError, KeyError, TypeError) as exc:
                frame, reason = None, "行情读取失败：" + type(exc).__name__
            if frame is None:
                dropped.append({"symbol": symbol, "reason": reason})
            else:
                fetched[symbol] = frame
            if progress is not None:
                progress({"stage": "data", "completed": index, "total": len(symbols)})
    if len(fetched) < 8:
        raise ValueError("可评估股票不足8只；请检查行情来源或扩大自选研究池")
    latest = max(frame.index.max() for frame in fetched.values())
    for symbol, frame in list(fetched.items()):
        if frame.index.max() != latest:
            dropped.append({"symbol": symbol, "reason": "最新日线与本次研究时点不一致"})
            del fetched[symbol]
    if len(fetched) < 8:
        raise ValueError("同一行情时点可评估股票不足8只")
    panel = _wide_from_fetched(fetched, include_amount=True)
    if "amount" in panel:
        panel["vwap"] = panel["amount"] / panel["volume"].replace(0, np.nan)
    coverage = {"universe": context["universe"], "requested": len(symbols), "used": len(fetched),
                "dropped": dropped, "roster": roster, "source": "Vibe Tencent DataLoader",
                "adjustment": "split_dividend", "volume_unit": "shares",
                "history_start": panel["close"].index.min().isoformat(),
                "history_end": panel["close"].index.max().isoformat()}
    return panel, fetched, names, coverage


def run_quant_opportunity(payload, progress=None):
    context = validate_context({key: value for key, value in payload.items() if key != "operation"})
    if context["plan_id"] not in {"multifactor", "low_volatility"} or context.get("plan_ids"):
        raise ValueError("quantitative plan required")
    from src.api.mona_opportunity_engine import compute_opportunities

    try:
        panel, _, names, coverage = load_opportunity_panel(context, progress)
        result = compute_opportunities(panel, scheme_id=context["plan_id"], horizon=MODES[context["mode"]],
                                       metadata={"point_in_time_fields": []}, progress=progress)
        result.pop("_holdout_signals")
        result.update(plan_id=context["plan_id"], coverage=coverage, mode=context["mode"])
        for candidate in result["candidates"]:
            candidate["name"] = names.get(candidate["symbol"], "")
            candidate["factor_support"] = candidate["support"]
            observed = sum(not item.get("imputed", False) for item in candidate.get("contributions", []))
            selected = result["factor_audit"]["selected"]
            candidate["support"] = [
                f"在本次{len(result['candidates'])}只可排序股票中，模型将其排在第{candidate['rank']}位。",
                f"本次模型使用{selected}项经去重的信号，其中这只股票有{observed}项实际观测值。",
            ]
            history = panel["close"][candidate["symbol"]].dropna()
            if len(history) >= 21:
                observed_change = float(history.iloc[-1] / history.iloc[-21] - 1)
                candidate["support"].append(f"近20个交易日复权价格变化{observed_change:+.1%}；这是行情事实，不是未来涨幅预测。")
            # Factor prices are adjusted; never label them as current raw quotes.
            candidate.pop("last_price", None)
            candidate.pop("change_pct", None)
        result["backtests"] = []
        if context["mode"] == "ultrashort":
            result["limitations"].insert(0, "当前量化使用日频数据；超短线结果仅为日级背景，不包含盘中选股信号。")
        return result
    except (OSError, ValueError, KeyError, TypeError) as exc:
        logger.warning("Opportunity preparation failed: %s", type(exc).__name__)
        message = str(exc) if isinstance(exc, ValueError) and str(exc).startswith(("可评估", "同一行情")) else "本次选股未能取得足够的行情或有效因子，请稍后重试或调整研究范围。"
        return {"status": "error", "message": message, "plan_id": context["plan_id"],
                "candidates": [], "limitations": ["未生成候选，未用样例或模型记忆补足结果。"]}


def register_mona_opportunity(app: FastAPI):
