"""Save candidate projections bound to the executing native research attempt."""
import json

from src.agent.tools import BaseTool


class SaveOpportunityCandidatesTool(BaseTool):
    name = "save_opportunity_candidates"
    description = (
        "Save the current opportunity research's structured candidates, support and risks. "
        "Sources are bound automatically from successful data-tool calls for each symbol in this attempt. "
        "Omit evidence_call_ids rather than guessing opaque call identifiers. "
        "Use an empty candidate list when no stocks satisfy the criteria; never invent scores."
    )
    is_readonly = False
    repeatable = True
    parameters = {"type": "object", "additionalProperties": False, "properties": {
        "as_of": {"type": "string", "description": "Actual source data cutoff, with missing timestamps explained."},
        "candidates": {"type": "array", "maxItems": 50, "items": {"type": "object", "additionalProperties": False,
            "properties": {"symbol": {"type": "string", "pattern": "^[0-9]{6}\\.(SH|SZ|BJ)$"},
                "support": {"type": "array", "items": {"type": "string"}, "minItems": 1, "maxItems": 8},
                "risks": {"type": "array", "items": {"type": "string"}, "minItems": 1, "maxItems": 8},
                "checks": {"type": "array", "minItems": 2, "maxItems": 5, "description": "For combined screening: every selected direction must have real supporting evidence; exclude conflicts and missing data.",
                    "items": {"type": "object", "additionalProperties": False, "properties": {
                        "plan_id": {"type": "string", "enum": ["multifactor", "low_volatility", "fundamental", "sector", "event"]},
                        "status": {"type": "string", "enum": ["supported", "contradicted", "missing"]},
                        "reason": {"type": "string"}}, "required": ["plan_id", "status", "reason"]}},
                "evidence_call_ids": {"type": "array", "items": {"type": "string"}, "minItems": 1}},
            "required": ["symbol", "support", "risks"]}},
        "limitations": {"type": "array", "items": {"type": "string"}, "maxItems": 20},
    }, "required": ["as_of", "candidates", "limitations"]}

    @classmethod
    def check_available(cls):
        # Only an opportunity Session may register a tool with its real identity.
        return False

    def __init__(self, session_id, attempt_id, tool_trail, context=None, quant_results=None):
        self.session_id, self.attempt_id, self.tool_trail = session_id, attempt_id, tool_trail
        self.context = context or {}
        self.quant_results = quant_results if quant_results is not None else {}

    def execute(self, **kwargs):
        from src.api.mona_opportunity import save_candidates

        try:
            value = save_candidates(self.session_id, self.attempt_id, self.tool_trail,
                                    kwargs.get("candidates"), kwargs.get("as_of"), kwargs.get("limitations"),
                                    context=self.context, quant_results=self.quant_results)
            return json.dumps(value, ensure_ascii=False)
        except (ValueError, TypeError, KeyError) as exc:
            return json.dumps({"error": str(exc)}, ensure_ascii=False)


class ScreenOpportunitiesTool(BaseTool):
    name = "screen_opportunities"
    description = (
        "Run actual native Alpha Zoo / multi-factor and ML stock selection within this "
        "opportunity session's bound universe and horizon. Audits all factors, uses training "
        "only to select inputs and validates on separate dates; includes native cost backtests. "
        "Use when the user's criteria call for quantitative ranking. Do not represent this "
        "daily-price method as financial-statement, industry or intraday validation."
    )
    is_readonly = False
    parameters = {"type": "object", "additionalProperties": False, "properties": {
        "plan_id": {"type": "string", "enum": ["multifactor", "low_volatility"]},
    }, "required": ["plan_id"]}

    @classmethod
    def check_available(cls):
        return False

    def __init__(self, session_id, attempt_id, context, quant_results=None):
        self.session_id, self.attempt_id, self.context = session_id, attempt_id, context
        self.quant_results = quant_results if quant_results is not None else {}

    def execute(self, **kwargs):
        from src.api.mona_opportunity import PLANS, _save_projection, run_quant_opportunity

        plan = kwargs.get("plan_id")
        if plan not in {"multifactor", "low_volatility"}:
            return json.dumps({"error": "invalid quantitative plan"})
        selected = self.context.get("plan_ids", [])
        if selected and plan not in selected:
            return json.dumps({"error": "quantitative method is outside the selected directions"})
        payload = {key: value for key, value in self.context.items() if key != "plan_ids"}
        payload.update(plan_id=plan, conditions="")
        result = run_quant_opportunity(payload)
        result.update(session_id=self.session_id, attempt_id=self.attempt_id)
        if result.get("status") != "error":
            if selected:
                # A component method must never overwrite the final combined result.
                _save_projection(self.session_id, self.attempt_id + "-" + plan, result)
                result = {"plan_id": plan, "title": PLANS[plan]["title"], "as_of": result["as_of"],
                          "candidates": [{key: value for key, value in item.items() if key != "contributions"}
                                         for item in result["candidates"][:5]],
                          "factor_audit": {key: value for key, value in result["factor_audit"].items() if key != "entries"},
                          "method": result["method"], "backtests": result.get("backtests", []),
                          "validations": result.get("validations", []), "limitations": result.get("limitations", [])}
                self.quant_results[plan] = result
            else:
                _save_projection(self.session_id, self.attempt_id, result)
        return json.dumps(result, ensure_ascii=False, allow_nan=False)
